SELECT ac.id, ac.approve_status, ac.approve_user_id, ac.approve_user_name, ac.approve_time, ac.invalid_status, ac.invalid_remark, ac.invalid_time, ac.source_code, ac.source_type, ac.source_id, ac.org_id, ac.org_name, ac.type, ac.code, ac.status, ac.change_method, ac.name, ac.unit, ac.qty, ac.start_use_date, ac.asset_code, ac.asset_location_id, ac.disposal_status, ac.remark, ac.create_time, ac.create_user_name, -- 明细表字段（不包含通用字段） acd.id as detailId, acd.source_detail_id, acd.asset_code as detailAssetCode, acd.asset_location_id as detailAssetLocationId, acd.qty as detailQty, acd.supplier_id, acd.supplier_name, acd.use_dept_name, acd.use_dept_id, acd.cost_type, acd.remark as detailRemark FROM asset_card ac LEFT JOIN asset_card_detail acd ON acd.main_id = ac.id AND acd.is_deleted = false WHERE ${params.sqlMap.default} AND ac.is_deleted = false
${params.permissionSql}
ORDER BY ac.create_time DESC

SELECT ac.id, ac.approve_status, ac.approve_user_id, ac.approve_user_name, ac.approve_time, ac.invalid_status, ac.invalid_remark, ac.invalid_time, ac.source_code, ac.source_type, ac.source_id, ac.org_id, ac.org_name, ac.type, ac.code, ac.status, ac.change_method, ac.name, ac.unit, ac.qty, ac.start_use_date, ac.asset_code, ac.asset_location_id, ac.disposal_status, ac.remark, ac.create_time, ac.create_user_name, -- 明细表字段（不包含通用字段） acd.id as detailId, acd.source_detail_id, acd.asset_code as detailAssetCode, acd.asset_location_id as detailAssetLocationId, acd.qty as detailQty, acd.supplier_id, acd.supplier_name, acd.use_dept_name, acd.use_dept_id, acd.cost_type, acd.remark as detailRemark FROM asset_card ac LEFT JOIN asset_card_detail acd ON acd.main_id = ac.id AND acd.is_deleted = false WHERE ${params.sqlMap.default} AND ac.is_deleted = false
AND ac.id IN
#{id}
${params.permissionSql}
ORDER BY ac.create_time DESC

SELECT approve_status AS tabFlag, count(*) AS count FROM asset_card WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
